// Regenerate data/menu.js from ../sample-menu.json:  node build-menu.js
const fs = require("fs"), path = require("path");
const src = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "sample-menu.json"), "utf8"));
const slug = s => s.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "").slice(0, 24);
const DEF = [["Media", "Half"], ["Entera", "Full"]];
const cats = [], dishes = [];
src.forEach((x, i) => {
  const cid = slug(x.category);
  if (!cats.some(c => c.id === cid)) cats.push({ id: cid, name: { es: x.category } });
  const prices = Array.isArray(x.price_eur) ? x.price_eur : [x.price_eur];
  const d = { id: "d" + (i + 1), cat: cid, name: { es: x.name }, desc: x.description ? { es: x.description } : {},
    variants: prices.map((p, k) => prices.length === 1 ? { label_es: "", label_en: "", price: Number(p) }
      : prices.length === 2 ? { label_es: DEF[k][0], label_en: DEF[k][1], price: Number(p) }
      : { label_es: "Opción " + (k + 1), label_en: "Option " + (k + 1), price: Number(p) }),
    chips: ["no_onions", "no_gluten", "extra_spicy", "sauce_side"] };
  if (prices.length > 1) d.labelsAssumed = true;
  dishes.push(d);
});
const menu = { restaurant: "Demo Restaurant", currency: "EUR", categories: cats, dishes,
  chips: { no_onions: { es: "Sin cebolla", en: "No onions" }, no_gluten: { es: "Sin gluten", en: "Gluten-free" },
    extra_spicy: { es: "Picante", en: "Spicy" }, sauce_side: { es: "Salsa aparte", en: "Sauce on the side" } } };
// JSON.stringify escapes quotes safely; also escape U+2028/9 and "</" for script safety
const js = JSON.stringify(menu, null, 1).replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029").replace(/<\//g, "<\\/");
fs.writeFileSync(path.join(__dirname, "data", "menu.js"), "/* GENERATED by build-menu.js from sample-menu.json. Internal prototype only - do not publish. */\nwindow.MENU = " + js + ";\n");
console.log(`dishes ${dishes.length}, categories ${cats.length}, multi-variant ${dishes.filter(d => d.variants.length > 1).length}`);
